# Appendix F｜Extractable DOC-04 Companion Validator Reference
The following script is executable reference code for companion cross-object semantics. Canonical Draft 2020-12 schema validation remains a separate Layer-1 step using the exact P2 schemas.
```python
#!/usr/bin/env python3
import argparse, json, sys
from datetime import datetime, timezone
EDGE_KINDS = {"SPEC","ACC","VER","EVD_EXPECTATION","DEL","GATE"}
TRACE_STATES = {"TRACE_CURRENT","TRACE_STALE","TRACE_BLOCKED","TRACE_NA_ACCEPTED"}
CRITICAL_AGENT_EVENTS = {"TOOL_CALL","TOOL_RESULT","HANDOFF_SEND","HANDOFF_RECEIVE","GUARDRAIL_DECISION","CHECKPOINT","RECOVERY","EFFECT_INTENT","EFFECT_OBSERVATION","EFFECT_RECONCILIATION"}
def fail(code, detail):
    raise ValueError(f"{code}: {detail}")
def index(rows, key):
    out={}
    for row in rows:
        k=row.get(key)
        if not k: fail("MISSING_ID", key)
        if k in out: fail("DUPLICATE_ID", k)
        out[k]=row
    return out
def parse_ts(v):
    return datetime.fromisoformat(v.replace("Z","+00:00"))
def validate_na(trace, g):
    rid=trace.get("na_rationale")
    rationale=g["na_rationales"].get(rid)
    if not rationale or rationale.get("state")!="ACCEPTED" or not str(rationale.get("rationale","")).strip():
        fail("NA_RATIONALE_INVALID", trace["requirement_id"])
    refs={
      "SPEC":trace.get("spec_ref"), "ACC":trace.get("acceptance_ref"), "VER":trace.get("verification_ref"),
      "EVD_EXPECTATION":trace.get("evidence_expectation_ref"), "DEL":trace.get("deliverable_ref"), "GATE":trace.get("gate")}
    if set(refs)!=EDGE_KINDS: fail("NA_EDGE_KIND_INTERNAL_ERROR", trace["requirement_id"])
    seen=set()

    for kind, ref in refs.items():
        row=g["na_edges"].get(ref)
        if not row: fail("NA_REQUIRED_EDGE_RESOLUTION_MISSING", f"{kind}:{ref}")
        if row.get("edge_kind")!=kind or row.get("resolution_kind")!="NOT_APPLICABLE_EDGE_RESOLUTION":
            fail("NA_EDGE_RESOLUTION_TYPE_MISMATCH", ref)
        if row.get("requirement_ref")!=trace["requirement_id"] or row.get("na_rationale_ref")!=rid:
            fail("NA_EDGE_RESOLUTION_BINDING_MISMATCH", ref)
        if row.get("state")!="ACCEPTED": fail("NA_EDGE_NOT_ACCEPTED", ref)
        seen.add(kind)
    if seen!=EDGE_KINDS: fail("NA_EDGE_SET_INCOMPLETE", trace["requirement_id"])
def validate_execution_return(r):
    if not r.get("operation_id") or not r.get("procedure_ref"): fail("OPERATION_PROCEDURE_BINDING_MISSING", r.get("return_id"))
    if parse_ts(r["ended_at"]) < parse_ts(r["started_at"]): fail("EXECUTION_INTERVAL_INVALID", r.get("return_id"))
    for k in ("stdout_ref","stderr_ref","raw_result_ref"):
        if k not in r: fail("RAW_EVIDENCE_REF_MISSING", f"{r.get('return_id')}:{k}")
    if "changed_artifacts" not in r or "changed_effects" not in r: fail("CHANGE_INVENTORY_MISSING", r.get("return_id"))
def validate_profile_extension(ext, core_tests):
    if ext.get("core_override") is not False: fail("CORE_OVERRIDE_FORBIDDEN", ext.get("extension_id"))
    added=set(ext.get("added_tests_or_oracles",[]))
    effective=set(ext.get("effective_tests_or_oracles", list(core_tests|added)))
    if not core_tests.issubset(effective): fail("PROFILE_REMOVED_CORE_TEST", ext.get("extension_id"))
def validate_gate_binding(row):
    s=row.get("trace_closure_state")
    if s not in TRACE_STATES: fail("TRACE_CLOSURE_STATE_INVALID", row.get("binding_trace_id"))
    gate=row.get("gate",{})
    if "result" in gate or "state" in gate: fail("GATE_TRACE_NAMESPACE_COLLISION", row.get("binding_trace_id"))
def validate_agent_trace(r):
    if r.get("event_class") in CRITICAL_AGENT_EVENTS and r.get("sampling_state") not in {"NOT_SAMPLED_CRITICAL","FULL_FIDELITY"}:
        fail("CRITICAL_TRACE_EVENT_MISSING", r.get("event_id"))
    if r.get("pii_redaction_state") not in {"PASS","NOT_APPLICABLE"}: fail("TRACE_REDACTION_INVALID", r.get("event_id"))
    if r.get("evidence_candidate_state")=="PASS": fail("TELEMETRY_DIRECT_PASS_FORBIDDEN", r.get("event_id"))
def validate_resume(r, subjects):
    if r.get("workflow_id")!="CROSS_SESSION_PIPELINE": fail("WORKFLOW_ID_MISMATCH", r.get("resume_packet_id"))
    sub=subjects.get(r.get("subject_id"))
    if not sub or sub.get("version")!=r.get("subject_version") or sub.get("hash")!=r.get("subject_hash"):
        fail("STALE_SUBJECT_HASH", r.get("resume_packet_id"))
    if r.get("from_session_id")==r.get("to_session_id"): fail("FOREIGN_SESSION_CONTEXT", r.get("resume_packet_id"))
    if parse_ts(r["expires_at"]) < parse_ts(r["issued_at"]): fail("EXPIRED_RESUME_PACKET", r.get("resume_packet_id"))
    if not r.get("purge_after"): fail("PURGE_POLICY_MISSING", r.get("resume_packet_id"))
def validate_sod(r):

    if r.get("profile")=="ASSURED":
        vals=[r.get("maker"),r.get("checker"),r.get("acceptor")]
        if None in vals or len(set(vals))<3: fail("SOD_COLLAPSE", r.get("binding_id"))
        if r.get("independent_qualifier") in {r.get("maker"),r.get("checker"),r.get("acceptor")}:
            fail("FALSE_INDEPENDENCE_CLAIM", r.get("binding_id"))
def validate_threat(r):
    req=("threat","asset","trust_boundary","abuse_case","prevention","detection","response","test_ref","oracle_ref","owner","residual_risk","evidence_expectation_ref")
    if any(not r.get(k) for k in req): fail("THREAT_BINDING_INCOMPLETE", r.get("threat_id"))
def validate_graph(doc):
    g={
      "na_rationales":index(doc.get("na_rationales",[]),"na_id"),
      "na_edges":index(doc.get("na_edges",[]),"na_edge_id")}
    for t in doc.get("traces",[]):
        if t.get("status")=="NOT_APPLICABLE": validate_na(t,g)
    for r in doc.get("execution_returns",[]): validate_execution_return(r)
    core=set(doc.get("core_tests_or_oracles",[]))
    for r in doc.get("profile_extensions",[]): validate_profile_extension(r,core)
    for r in doc.get("gate_bindings",[]): validate_gate_binding(r)
    for r in doc.get("agent_traces",[]): validate_agent_trace(r)
    subjects=index(doc.get("subjects",[]),"subject_id")
    for r in doc.get("cross_session_packets",[]): validate_resume(r,subjects)
    for r in doc.get("role_bindings",[]): validate_sod(r)
    for r in doc.get("threat_bindings",[]): validate_threat(r)
    return {"result":"PASS","first_failing_invariant":None}
def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("--graph",required=True)
    ap.add_argument("--report",required=True)
    ap.add_argument("--canonical-schemas",required=False)
    a=ap.parse_args()
    try:
        doc=json.load(open(a.graph,"r",encoding="utf-8"))
