def section(text, start, end):
    return text.split(start,1)[1].split(end,1)[0]
def parse_a(text):
    a = section(text, "# Appendix A｜", "# Appendix B｜")
    rows=[]
    pat=re.compile(r'^\|\s*(STD-REQ-[A-F0-9]{8})\s*\|\s*(.*?)\|\s*(TEST-[A-F0-9]{8})\s*\|\s*(OR-[A-F0-9]{8})\s*\|\s*(ALL|APPLICABLE_PROFILE)\s*\|')
    for line in a.splitlines():
        m=pat.match(line)
        if m:
            rows.append((m.group(1),m.group(3),m.group(4),m.group(5)))
    return rows
def tuple_hash(rows):
    data="".join(f"{a}\t{b}\t{c}\t{d}\n" for a,b,c,d in rows)
    return hashlib.sha256(data.encode()).hexdigest()
def donor_counts(text):
    f=section(text,"# Appendix F｜","# Appendix G｜")
    return {
        "CAND":len(set(re.findall(r'\bCAND-\d{2}\b',f))),
        "NOBJ":len(set(re.findall(r'\bNOBJ-\d{3}\b',f))),
        "ECP":len(set(re.findall(r'\bECP-\d{2}\b',f))),
        "ADD":len(set(re.findall(r'\bADD-\d{2}\b',f))),
        "MSC":len(set(re.findall(r'\bMSC-TECH-\d{3}\b',f))),
        "TQ":len(set(re.findall(r'\bTQ-TECH-\d{3}\b',f))),
    }
def profile_counts(text):
    return {
        "SYS_PI":len(set(re.findall(r'\bSYS-PI-\d{2}\b',text))),
        "SYS_PD":len(set(re.findall(r'\bSYS-PD-\d{2}\b',text))),
        "SK_PI":len(set(re.findall(r'\bSK-PI-\d{2}\b',text))),
        "SK_PD":len(set(re.findall(r'\bSK-PD-\d{2}\b',text))),
        "AH_PI":len(set(re.findall(r'\bAH-PI-\d{2}\b',text))),

        "AH_PD":len(set(re.findall(r'\bAH-PD-\d{2}\b',text))),
    }
def effect_guard(x):
    if not x.get("observation_refs"):
        return 3,"EFFECT_RECONCILIATION_OBSERVATION_MISSING"
    if not x.get("readback_refs"):
        return 3,"EFFECT_RECONCILIATION_READBACK_MISSING"
    if not x.get("oracle"):
        return 3,"EFFECT_RECONCILIATION_ORACLE_MISSING"
    if not x.get("checker"):
        return 3,"EFFECT_RECONCILIATION_CHECKER_MISSING"
    state=x.get("state"); next_action=x.get("next_action")
    if state=="CONFIRMED_EFFECT" and next_action!="PROMOTE_EVIDENCE":
        return 3,"EFFECT_RECONCILIATION_CONFIRMED_WITHOUT_PROMOTION"
    if state!="CONFIRMED_EFFECT" and next_action=="PROMOTE_EVIDENCE":
        return 3,"EFFECT_RECONCILIATION_FALSE_PROMOTION"
    return 0,None
def extract_json(text, start, end):
    s=section(text,start,end)
    m=re.search(r'```json\n(.*?)\n```',s,re.S)
    if not m:
        raise AssertionError(f"missing JSON block {start}")
    return json.loads(m.group(1))
def base_checks(text):
    out={}
    rows=parse_a(text)
    out["R2-G01_86_rows"]=(len(rows)==86 and len({r[0] for r in rows})==86 and tuple_hash(rows)==EXPECTED_TUPLE_HASH)
    out["R2-G01_0CB9_tuple"]=(("STD-REQ-0CB9A2A0","TEST-0CB9A2A0","OR-0CB9A2A0","APPLICABLE_PROFILE") in rows)
    atomics=set(re.findall(r'\b(?:DT-\d{2}-C\d{2}|FX-(?:HPI|APPR|FPASS|DRIFT)-001-C\d{2})\b',text))
    out["R2-G02_atomicity"]=ATOMIC_REQUIRED <= atomics
    cov=section(text,"# Appendix I｜","# Appendix E｜") if "# Appendix E｜" in text else text.split("# Appendix I｜",1)[1]
    cov_rows=[ln for ln in cov.splitlines() if re.match(r'^\|\s*(A1_BLUEPRINT|A3_SKELETON|PRODUCTION_INSTRUCTION|AUDIT_CONTROLLER)\s*\|',ln)]
    out["R2-G03_coverage_219"]=(len(cov_rows)==219)
