    cur=load(root/manifest["currentness_ref"])
    now=datetime.now(timezone.utc)
    for row in cur["records"]:
        if not row["selected"]: continue
        checked=datetime.fromisoformat(row["checked_at"].replace("Z","+00:00"))
        if checked+timedelta(hours=row["ttl_hours"]) <= now:
            findings.append({"class":"CURRENTNESS_TTL_EXPIRED","ref":row["candidate_id"]})
        for k in ("security_status","license_status","compatibility_status"):
            if row[k]!="PASS":
                findings.append({"class":f'{k.upper()}_NOT_PASS',"ref":row["candidate_id"]})
    # PASS evidence must bind a known current subject hash.
    current_subject_hashes=set()
    for obj in object_docs.values():
        for key in ("content_hash","subject_hash"):
            if isinstance(obj.get(key),str):
                current_subject_hashes.add(obj[key])
    for path,obj in object_docs.items():
        if obj.get("evidence_id") and obj.get("result")=="PASS":
            if obj.get("subject_hash") not in current_subject_hashes:
                findings.append({"class":"EVIDENCE_FOREIGN_OR_STALE_SUBJECT","ref":path})
    result={"result":"PASS" if not findings else "FAIL","finding_count":len(findings),"findings":findings}
    print(json.dumps(result,ensure_ascii=False,indent=2))
    return 0 if not findings else 4
if __name__=="__main__":
    raise SystemExit(main())
