```python
# SBL proposal-only. Native Oracle runner MUST be supplied by PIPD DOC07 Owner.
def select_cell(c, context):
    native_all = context.get("native_all")
    if native_all is None: return "HOLD", "NATIVE_ALL_UNBOUND"
    if context.get("mode") == "PREW3_SHADOW" and context.get("effect_requested"):
        return "DENY", "DENY_NO_NATIVE_EFFECT"
    for k in ("source_sha", "subject_sha", "source_rule", "official_oracle_binding"):
        if not context.get(k): return "HOLD", "SOURCE_OR_ORACLE_UNBOUND"
    pred = context["eval_named_predicate"](c["precondition"])
    if pred is None: return "HOLD", "PREDICATE_UNRESOLVED"
    if native_all: return "REQUIRED", "NATIVE_ALL"
    if pred: return "REQUIRED", "CLASS_ORACLE_TRIGGER"
    decision = context.get("original_owner_na_envelope")
    if not decision or not decision.get("signature") or not decision.get("expiry"):
        return "HOLD", "NA_OWNER_DECISION_MISSING"
    return "N_A_WITH_REASON", "ORIGINAL_OWNER_SIGNED_NA"
def apply_mutation(base, mutation):
    import copy
    out = copy.deepcopy(base)
    path = mutation["path"].lstrip("/").split("/")
    node = out
    for k in path[:-1]: node = node.setdefault(k,{})
    node[path[-1]] = mutation["value"]
    assert out != base, "NON_DESTRUCTIVE_MUTATION"
    return out

